30	/// Convert `FormatConfig` into `OxfmtOptions`.
31	///
32	/// # Errors
33	/// Returns error if any option value is invalid
34	pub fn to_oxfmt_options(config: FormatConfig) -> Result<OxfmtOptions, String> {
35	    // Not yet supported options:
36	    // [Prettier] experimentalOperatorPosition: "start" | "end"
37	    // [Prettier] experimentalTernaries: boolean
38	    if config.experimental_operator_position.is_some() {
39	        return Err("Unsupported option: `experimentalOperatorPosition`".to_string());
40	    }
41	    if config.experimental_ternaries.is_some() {
42	        return Err("Unsupported option: `experimentalTernaries`".to_string());
43	    }
44	
45	    // All values are based on defaults from `FormatOptions::default()`
46	    let mut format_options = FormatOptions::default();
47	
48	    // [Prettier] useTabs: boolean
49	    if let Some(use_tabs) = config.use_tabs {
50	        format_options.indent_style = if use_tabs { IndentStyle::Tab } else { IndentStyle::Space };
51	    }
52	
53	    // [Prettier] tabWidth: number
54	    if let Some(width) = config.tab_width {
55	        format_options.indent_width =
56	            IndentWidth::try_from(width).map_err(|e| format!("Invalid tabWidth: {e}"))?;
57	    }
58	
59	    // [Prettier] endOfLine: "lf" | "cr" | "crlf" | "auto"
60	    // NOTE: "auto" is not supported
61	    if let Some(ending) = config.end_of_line {
62	        format_options.line_ending = match ending {
63	            EndOfLineConfig::Lf => LineEnding::Lf,
64	            EndOfLineConfig::Crlf => LineEnding::Crlf,
65	            EndOfLineConfig::Cr => LineEnding::Cr,
66	        };
67	    }
68	
69	    // [Prettier] printWidth: number
70	    if let Some(width) = config.print_width {
71	        format_options.line_width =
72	            LineWidth::try_from(width).map_err(|e| format!("Invalid printWidth: {e}"))?;
73	    }
74	
75	    // [Prettier] singleQuote: boolean
76	    if let Some(single_quote) = config.single_quote {
77	        format_options.quote_style =
78	            if single_quote { QuoteStyle::Single } else { QuoteStyle::Double };
79	    }
80	
81	    // [Prettier] jsxSingleQuote: boolean
82	    if let Some(jsx_single_quote) = config.jsx_single_quote {
