45	impl SortImportsOptions {
46	    /// Validate option combinations.
47	    ///
48	    /// # Errors
49	    /// Returns an error message if incompatible options are set.
50	    pub fn validate(&self) -> Result<(), String> {
51	        if self.partition_by_newline && self.newline_boundary_overrides.iter().any(Option::is_some)
52	        {
53	            return Err("`partitionByNewline` and per-group `{ \"newlinesBetween\" }` markers cannot be used together".to_string());
54	        }
55	        if self.partition_by_newline && self.newlines_between {
56	            return Err(
57	                "`partitionByNewline: true` and `newlinesBetween: true` cannot be used together"
58	                    .to_string(),
59	            );
60	        }
61	        Ok(())
62	    }
63	}
