142	/// Returns default groups configuration for organizing imports.
143	pub fn default_groups() -> Vec<Vec<GroupEntry>> {
144	    // Helper to parse a predefined group name
145	    let p = |s: &str| GroupEntry::Predefined(GroupName::parse(s).unwrap());
146	    // Our policy: far to near, built-in to local.
147	    // Do not include side effects by default, it may break some code if moved around.
148	    vec![
149	        vec![p("builtin")],
150	        vec![p("external")],
151	        vec![p("internal"), p("subpath")],
152	        vec![p("parent"), p("sibling"), p("index")],
153	        vec![p("style")],
154	        vec![GroupEntry::Unknown],
155	    ]
