9	/// Resolve ignore file paths from CLI args or defaults.
10	///
11	/// Called early (before walk) to validate that specified ignore files exist.
12	pub(super) fn resolve_ignore_paths(
13	    cwd: &Path,
14	    ignore_paths: &[PathBuf],
15	) -> Result<Vec<PathBuf>, String> {
16	    if !ignore_paths.is_empty() {
17	        let mut result = Vec::with_capacity(ignore_paths.len());
18	        for path in ignore_paths {
19	            let path = normalize_relative_path(cwd, path);
20	            if !path.exists() {
21	                return Err(format!("{}: File not found", path.display()));
22	            }
23	            result.push(path);
24	        }
25	        return Ok(result);
26	    }
27	
28	    // Default: search for .prettierignore in cwd
29	    Ok(std::iter::once(".prettierignore")
30	        .filter_map(|file_name| {
31	            let path = cwd.join(file_name);
32	            path.exists().then_some(path)
33	        })
34	        .collect())
35	}
