37	/// Build global ignore matchers from ignore files and CLI exclude patterns.
38	///
39	/// These are scope-independent and block both files and directories across all scopes.
40	/// Each matcher has its own root for pattern resolution:
41	/// - ignore files use their parent dir
42	/// - excludes use `cwd`
43	///
44	/// Git ignore files are handled by `WalkBuilder` itself.
45	pub(super) fn build_global_ignore_matchers(
46	    cwd: &Path,
47	    exclude_patterns: &[String],
48	    ignore_paths: &[PathBuf],
49	) -> Result<Vec<Gitignore>, String> {
50	    let mut matchers: Vec<Gitignore> = vec![];
51	
52	    // 1. Formatter ignore files (.prettierignore, --ignore-path)
53	    // Paths are already resolved and validated by `resolve_ignore_paths()`
54	    for ignore_path in ignore_paths {
55	        let (gitignore, err) = Gitignore::new(ignore_path);
56	        if let Some(err) = err {
57	            return Err(format!("Failed to parse ignore file {}: {err}", ignore_path.display()));
58	        }
59	        matchers.push(gitignore);
60	    }
61	
62	    // 2. `!` prefixed paths (CLI excludes, relative to cwd)
63	    if !exclude_patterns.is_empty() {
64	        let mut builder = GitignoreBuilder::new(cwd);
65	        for pattern in exclude_patterns {
66	            // Remove the leading `!` because `GitignoreBuilder` uses `!` as negation
67	            let pattern =
68	                pattern.strip_prefix('!').expect("There should be a `!` prefix, already checked");
69	            if builder.add_line(None, pattern).is_err() {
70	                return Err(format!("Failed to add ignore pattern `{pattern}` from `!` prefix"));
71	            }
72	        }
73	        let gitignore = builder.build().map_err(|_| "Failed to build ignores".to_string())?;
74	        matchers.push(gitignore);
75	    }
76	
77	    Ok(matchers)
78	}
