80	/// Check if a path should be ignored by any of the matchers.
81	/// A path is ignored if any matcher says it's ignored (and not whitelisted in that same matcher).
82	///
83	/// When `check_ancestors: true`, also checks if any parent directory is ignored.
84	/// This is more expensive, but necessary when paths (to be ignored) are passed directly via CLI arguments.
85	/// For normal walking, walk is done in a top-down manner, so only the current path needs to be checked.
86	pub(super) fn is_ignored(
87	    matchers: &[Gitignore],
88	    path: &Path,
89	    is_dir: bool,
90	    check_ancestors: bool,
91	) -> bool {
92	    for matcher in matchers {
93	        let matched = if check_ancestors {
94	            // `matched_path_or_any_parents()` panics if path is not under matcher's root.
95	            // Skip this matcher if the path is outside its scope.
96	            if !path.starts_with(matcher.path()) {
97	                continue;
98	            }
99	            matcher.matched_path_or_any_parents(path, is_dir)
100	        } else {
101	            matcher.matched(path, is_dir)
102	        };
103	        if matched.is_ignore() && !matched.is_whitelist() {
104	            return true;
105	        }
106	    }
107	    false
108	}
