21	impl DiagnosticReporter for DefaultReporter {
22	    fn render_error(&mut self, error: Error) -> Option<String> {
23	        // Collect diagnostics for rendering in finish() at once
24	        self.diagnostics.push(error);
25	        None
26	    }
27	
28	    fn finish(&mut self, _result: &DiagnosticResult) -> Option<String> {
29	        let mut output = String::new();
30	
31	        // Render all diagnostics (errors only, no warnings)
32	        for diagnostic in &self.diagnostics {
33	            self.handler.render_report(&mut output, diagnostic.as_ref()).unwrap();
34	        }
35	
